const r = await tools.exec_command({cmd:"python - <<'PY'
import csv,collections,re,datetime,ast
base='/app/dataset/'
with open(base+'employees.csv',newline='',encoding='utf-8-sig') as f:E=list(csv.DictReader(f))
with open(base+'tasks.csv',newline='',encoding='utf-8-sig') as f:T=list(csv.DictReader(f))
with open(base+'timesheet.csv',newline='',encoding='utf-8-sig') as f:S=list(csv.DictReader(f))
emps={e['PESEL']:e for e in E}; tasks={t['task_id']:t for t in T}
print('columns',S[0].keys()); print('rows lacking values/columns')
for x in S:
 if len(x)!=8 or any(v is None for v in x.values()): print(x)
print('\nEMPLOYEES:')
for e in E: print(e['PESEL'],e['date_of_birth'],e['hire_date'],e['hourly_rate'],e['first_name'],e['last_name'])
print('\nUnknown employee IDs and counts:')
ct=collections.Counter(x['employee_id'] for x in S if x['employee_id'] not in emps)
for id,n in ct.items():
 print('\n',id,n)
 for x in S:
  if x['employee_id']==id: print(x)
print('\nBAD TASK LISTS')
for x in S:
 try: ast.literal_eval(x['performed_tasks'])
 except Exception as e: print(x,'ERROR',e)
print('\nINVALID DATES')
for x in S:
 try: datetime.date.fromisoformat(x['date'])
 except Exception as e: print(x,'ERROR',e)
print('\nDuplicates IDs',[(k,v) for k,v in collections.Counter(x['id'] for x in S).items() if v>1])
# row consistency for parseable task ids / task completeness
issues=collections.Counter(); examples=collections.defaultdict(list)
for x in S:
 tidlist=[int(z) for z in re.findall(r'\d+',x['performed_tasks'])]
 bonus=sum(float(tasks[str(k)]['pay_per_completion']) for k in tidlist if str(k) in tasks)
 if len(tidlist)!=len(set(tidlist)): issues['duplicate task in row']+=1; examples['duplicate task in row'].append(x)
 if any(str(k) not in tasks for k in tidlist): issues['unknown task']+=1; examples['unknown task'].append(x)
 if abs(float(x['bonus'])-bonus)>0.01: issues['bonus vs tasklist']+=1; examples['bonus vs tasklist'].append((x['id'],x['bonus'],bonus,x['performed_tasks']))
 e=emps.get(x['employee_id'])
 if e:
  expected=float(e['hourly_rate'])*float(x['hours_worked'])+float(x['bonus'])
  if abs(float(x['salary_amount'])-expected)>0.01: issues['salary vs hours+bonus']+=1; examples['salary vs hours+bonus'].append((x['id'],x['salary_amount'],expected))
print('\nISSUES',issues)
for k,v in examples.items():print('\n',k,'first rows',v[:20])
PY",yield_time_ms:10000,max_output_tokens:12000});
