const r = await tools.exec_command({cmd:"cat > /app/answer.py <<'PY'
import calendar
import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP

DATA_DIR = "/app/dataset"

# These IDs are the unique nearest matches to roster PESELs; each has a
# malformed birth-date prefix or check digits in the timesheet.
PESEL_CORRECTIONS = {
    "84731091580": "87031491580",
    "62020111425": "65020111422",
    "16102016795": "96102016751",
    "68011910138": "68011810139",
    "15720759071": "75020759171",
}


def _read_csv(filename):
    with open(f"{DATA_DIR}/{filename}", newline="", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))


def _parse_date_clamped(value):
    """Parse YYYY-MM-DD, correcting overflow days to that month's last day."""
    year, month, day = (int(part) for part in value.split("-"))
    last_day = calendar.monthrange(year, month)[1]
    return date(year, month, min(day, last_day))


def _month_after(year, month):
    return (year + (month == 12), 1 if month == 12 else month + 1)


def _billing_start(year, month, weekday):
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def answer() -> dict[str, list[int]]:
    employees = {
        row["PESEL"]: Decimal(row["hourly_rate"])
        for row in _read_csv("employees.csv")
    }
    tasks = {
        row["task_id"]: Decimal(row["pay_per_completion"])
        for row in _read_csv("tasks.csv")
    }
    timesheets = _read_csv("timesheet.csv")

    parsed_rows = []
    for row in timesheets:
        try:
            work_date = _parse_date_clamped(row["date"])
            hours = Decimal(row["hours_worked"])
        except (ValueError, ArithmeticError):
            continue
        if hours < 0:
            continue
        employee_id = PESEL_CORRECTIONS.get(row["employee_id"], row["employee_id"])
        if employee_id not in employees:
            continue
        parsed_rows.append((row, work_date, hours, employee_id))

    if not parsed_rows:
        return {pesel: [] for pesel in employees}

    earliest_date = min(work_date for _, work_date, _, _ in parsed_rows)
    latest_date = max(work_date for _, work_date, _, _ in parsed_rows)
    start_weekday = earliest_date.weekday()

    # A billing month starts on the first occurrence of the inherited weekday.
    # The first cycle starts at the earliest dataset record itself.
    starts = []
    year, month = earliest_date.year, earliest_date.month
    while (year, month) <= (latest_date.year, latest_date.month):
        start = _billing_start(year, month, start_weekday)
        if (year, month) == (earliest_date.year, earliest_date.month):
            start = earliest_date
        starts.append(start)
        year, month = _month_after(year, month)

    totals = {pesel: [Decimal("0") for _ in starts] for pesel in employees}
    for row, work_date, hours, employee_id in parsed_rows:
        period_index = -1
        for i, start in enumerate(starts):
            if start <= work_date:
                period_index = i
            else:
                break
        if period_index < 0:
            continue

        # Extracting the numeric IDs also repairs lists with a missing bracket.
        # Task IDs absent from tasks.csv cannot be valued and are excluded.
        task_bonus = sum(
            (tasks[task_id] for task_id in re.findall(r"\d+", row["performed_tasks"])
             if task_id in tasks),
            Decimal("0"),
        )
        hourly_pay = employees[employee_id] * hours
        totals[employee_id][period_index] += hourly_pay + task_bonus

    return {
        pesel: [int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP)) for value in values]
        for pesel, values in totals.items()
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f)
